package com.lolfm.composition;
import com.lolfm.champion.*;import com.lolfm.domain.Position;import java.util.*;
public record TeamCompositionLineup(Map<Position,ChampionRoleKey> championsByPosition){public TeamCompositionLineup{Objects.requireNonNull(championsByPosition);EnumMap<Position,ChampionRoleKey>copy=new EnumMap<>(Position.class);for(var e:championsByPosition.entrySet()){Objects.requireNonNull(e.getKey());Objects.requireNonNull(e.getValue());if(e.getKey()!=e.getValue().position())throw new IllegalArgumentException("Role position mismatch");if(copy.put(e.getKey(),e.getValue())!=null)throw new IllegalArgumentException("Duplicate position");}if(copy.size()!=Position.values().length||!copy.keySet().containsAll(EnumSet.allOf(Position.class)))throw new IllegalArgumentException("Exactly five positions required");if(copy.values().stream().map(ChampionRoleKey::championId).distinct().count()!=copy.size())throw new IllegalArgumentException("Duplicate champion");championsByPosition=Map.copyOf(copy);}}
